-- Economics final module. Run seed_econ_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'economics';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Final Assessment: Economic Choices Report and Presentation$j$, $j${"prompt": "Write an economics report of at least 500 words and prepare a short presentation of its main ideas. Choose one topic: (a) how supply and demand set the price of one real product in your community, such as gasoline, housing or groceries in South Florida; (b) the plan for a small business you could start, with its costs, prices and profit; (c) how inflation, interest rates or unemployment affect one family and what the Federal Reserve or Congress can do; (d) the effects of trade or a tariff on one product you use; or (e) a topic approved by your administrator. Write complete sentences and label each part. Proverbs 21:5 says, The thoughts of the diligent tend only to plenty; but of every one that is hasty only to want.\n\nPart 1: Question and Thesis. State a clear question and a thesis about your topic.\nPart 2: Sources. List at least three reliable sources, such as the Bureau of Labor Statistics, the Bureau of Economic Analysis, the Federal Reserve, a business or a news report, and tell how you judged each.\nPart 3: The Report. Explain your topic with an introduction, at least three body paragraphs and a conclusion. Use at least four terms from this course, such as scarcity, opportunity cost, equilibrium, competition, GDP, inflation or comparative advantage, and show how each applies.\nPart 4: Scripture Connection. Connect your topic to a passage of Scripture in the King James Version and explain the link.\nPart 5: Personal Action Plan. Describe one step you will take to be a wise steward, such as a budget, a savings goal, a plan for credit or a career plan.\nPart 6: Presentation Plan. Write a three part outline and an opening line for a three minute talk.", "rubric": "100 points. Part 1, question and thesis: 10 points. Part 2, sources: 10 points. Part 3, report content, accuracy and use of course terms: 40 points. Part 4, Scripture connection: 8 points. Part 5, personal action plan: 12 points. Part 6, presentation plan: 10 points. Grammar, conventions and respectful tone: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Economic Choices Report and Presentation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Final Exam: Economics$j$, $j${"questions": [{"q": "Scarcity means:", "options": ["Goods are free", "Wants are unlimited but resources are limited", "Money has no value", "Everyone is poor"]}, {"q": "The value of the next best alternative you give up is the:", "options": ["Equilibrium price", "Tariff", "Profit", "Opportunity cost"]}, {"q": "An economy in which individuals and businesses decide through voluntary trade is a:", "options": ["Command economy", "Embargo", "Market economy", "Traditional economy"]}, {"q": "When the price is above equilibrium, there is a:", "options": ["Shortage", "Monopoly", "Surplus", "Deficit"]}, {"q": "A market with a few large sellers, such as airlines, is an:", "options": ["Barter market", "Oligopoly", "Perfect competition", "Monopoly"]}, {"q": "Profit equals:", "options": ["Total revenue minus total costs", "Wages plus rent", "Total costs minus revenue", "Taxes minus revenue"]}, {"q": "Education and training increase a worker's:", "options": ["Fixed costs", "Human capital", "Deficit", "Tariffs"]}, {"q": "The Federal Reserve System was created in:", "options": ["1933", "1776", "1913", "1865"]}, {"q": "The FDIC protects:", "options": ["Stock prices", "Business profits", "Imports", "Bank deposits"]}, {"q": "A good that everyone shares and no one can easily be kept from using is a:", "options": ["Quota", "Private good", "Luxury", "Public good"]}, {"q": "GDP is the market value of:", "options": ["The national debt", "Only government spending", "All final goods and services produced in a country in a year", "Only exports"]}, {"q": "To slow inflation, the Federal Reserve would usually:", "options": ["Ban all imports", "Raise interest rates", "Cut taxes", "Lower interest rates"]}, {"q": "A tax on imported goods is a:", "options": ["Deficit", "Tariff", "Quota", "Embargo"]}, {"q": "1,000 dollars at 5 percent simple interest for 3 years earns:", "options": ["1,157 dollars", "150 dollars", "500 dollars", "50 dollars"]}, {"q": "Proverbs 22:7 says, The rich ruleth over the poor, and the borrower is:", "options": ["Free of debt", "Rich in time", "Servant to the lender", "Master of the bank"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Economics$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,2,2,1,0,1,2,3,3,2,1,1,1,2}'::int[], array[$j$Scarcity is the basic economic problem.$j$,$j$Every choice has an opportunity cost.$j$,$j$Prices guide choices in a market economy.$j$,$j$Sellers offer more than buyers want.$j$,$j$An oligopoly has a few large firms.$j$,$j$A business earns profit when revenue is above costs.$j$,$j$Human capital is the skill and knowledge of workers.$j$,$j$Congress passed the Federal Reserve Act in 1913.$j$,$j$It insures deposits at member banks.$j$,$j$National defense is a public good.$j$,$j$It is the main measure of national output.$j$,$j$Higher rates cool spending and borrowing.$j$,$j$Tariffs raise the price of imports.$j$,$j$1,000 times 0.05 times 3 equals 150.$j$,$j$Scripture warns that debt brings obligation.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Economics$j$ on conflict (item_id) do nothing;
end
$seed$;
